-- Load production.FactFacilityYearProduction (fact).
-- One stored procedure per destination table (DE Policy v2, 5.3).
-- Generated by `python -m fde render` from models/gold/production/FactFacilityYearProduction.yml. Do not edit: change the spec and render again.

CREATE OR ALTER PROCEDURE [production].[LoadFactFacilityYearProduction]
    @LoadDate date,
    @LoadStepID varchar(36)
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Now datetime2(6) = SYSUTCDATETIME();
    DECLARE @MaxKey bigint = (SELECT COALESCE(MAX([FactFacilityYearProduction_SK]), 0)
                              FROM [production].[FactFacilityYearProduction] WHERE [FactFacilityYearProduction_SK] > 0);

    MERGE [production].[FactFacilityYearProduction] AS target
    USING (
        SELECT
            CAST(s.[FacilityYear_BK] AS varchar(30)) AS [FacilityYear_BK],
            CAST(s.[DimFacility_SK] AS bigint) AS [DimFacility_SK],
            CAST(s.[ReportingYear] AS int) AS [ReportingYear],
            CAST(s.[OreMinedTonnes] AS decimal(28,4)) AS [OreMinedTonnes],
            CAST(s.[OreProcessedTonnes] AS decimal(28,4)) AS [OreProcessedTonnes],
            CAST(s.[ConcentrateTonnes] AS decimal(28,4)) AS [ConcentrateTonnes],
            CAST(s.[WasteTonnes] AS decimal(28,4)) AS [WasteTonnes],
            @MaxKey + ROW_NUMBER() OVER (ORDER BY s.[FacilityYear_BK]) AS [NewKey]
        FROM [stage].[FactFacilityYearProductionSource] AS s
    ) AS source
    ON target.[FacilityYear_BK] = source.[FacilityYear_BK]
    WHEN MATCHED AND (
        (target.[DimFacility_SK] <> source.[DimFacility_SK] OR (target.[DimFacility_SK] IS NULL AND source.[DimFacility_SK] IS NOT NULL) OR (target.[DimFacility_SK] IS NOT NULL AND source.[DimFacility_SK] IS NULL))
        OR (target.[ReportingYear] <> source.[ReportingYear] OR (target.[ReportingYear] IS NULL AND source.[ReportingYear] IS NOT NULL) OR (target.[ReportingYear] IS NOT NULL AND source.[ReportingYear] IS NULL))
        OR (target.[OreMinedTonnes] <> source.[OreMinedTonnes] OR (target.[OreMinedTonnes] IS NULL AND source.[OreMinedTonnes] IS NOT NULL) OR (target.[OreMinedTonnes] IS NOT NULL AND source.[OreMinedTonnes] IS NULL))
        OR (target.[OreProcessedTonnes] <> source.[OreProcessedTonnes] OR (target.[OreProcessedTonnes] IS NULL AND source.[OreProcessedTonnes] IS NOT NULL) OR (target.[OreProcessedTonnes] IS NOT NULL AND source.[OreProcessedTonnes] IS NULL))
        OR (target.[ConcentrateTonnes] <> source.[ConcentrateTonnes] OR (target.[ConcentrateTonnes] IS NULL AND source.[ConcentrateTonnes] IS NOT NULL) OR (target.[ConcentrateTonnes] IS NOT NULL AND source.[ConcentrateTonnes] IS NULL))
        OR (target.[WasteTonnes] <> source.[WasteTonnes] OR (target.[WasteTonnes] IS NULL AND source.[WasteTonnes] IS NOT NULL) OR (target.[WasteTonnes] IS NOT NULL AND source.[WasteTonnes] IS NULL))
    ) THEN UPDATE SET
        [DimFacility_SK] = source.[DimFacility_SK],
        [ReportingYear] = source.[ReportingYear],
        [OreMinedTonnes] = source.[OreMinedTonnes],
        [OreProcessedTonnes] = source.[OreProcessedTonnes],
        [ConcentrateTonnes] = source.[ConcentrateTonnes],
        [WasteTonnes] = source.[WasteTonnes],
        [LastUpdateLoadStepID] = @LoadStepID,
        [LastUpdateTimestamp] = @Now
    WHEN NOT MATCHED BY TARGET THEN INSERT (
        [FactFacilityYearProduction_SK],
        [FacilityYear_BK],
        [DimFacility_SK],
        [ReportingYear],
        [OreMinedTonnes],
        [OreProcessedTonnes],
        [ConcentrateTonnes],
        [WasteTonnes],
        [InsertLoadStepID],
        [InsertTimestamp],
        [LastUpdateLoadStepID],
        [LastUpdateTimestamp]
    ) VALUES (
        source.[NewKey],
        source.[FacilityYear_BK],
        source.[DimFacility_SK],
        source.[ReportingYear],
        source.[OreMinedTonnes],
        source.[OreProcessedTonnes],
        source.[ConcentrateTonnes],
        source.[WasteTonnes],
        @LoadStepID,
        @Now,
        @LoadStepID,
        @Now
    );
END
GO
